import SwiftUI
import AppKit

/// The Hyena mark. Geometry lives in LogoArtwork.swift, generated by
/// scripts/generate-logo.py, on Apple's 1024-pt macOS icon grid.
enum LogoArtwork {
    static let canvas: CGFloat = 1024
    static let body = CGRect(x: 100, y: 100, width: 824, height: 824)
    static let cornerRadius: CGFloat = 185
    static let background = Gradient(stops: [
        .init(color: Color(red: 0.173, green: 0.184, blue: 0.400), location: 0),
        .init(color: Color(red: 0.102, green: 0.106, blue: 0.247), location: 0.55),
        .init(color: Color(red: 0.047, green: 0.051, blue: 0.125), location: 1),
    ])
}

struct LogoLayer {
    enum Shape {
        case path(String)
        case ellipse(center: CGPoint, rx: CGFloat, ry: CGFloat, degrees: CGFloat)
    }
    enum Fill {
        case solid(Color)
        case linear([Gradient.Stop], from: CGPoint, to: CGPoint)
        case radial([Gradient.Stop], center: CGPoint, radius: CGFloat)
    }
    let shape: Shape
    let fill: Fill
    var strokeWidth: CGFloat?

    init(shape: Shape, fill: Fill, strokeWidth: CGFloat? = nil) {
        self.shape = shape
        self.fill = fill
        self.strokeWidth = strokeWidth
    }

    var path: Path {
        switch shape {
        case .path(let data): SVGPath.parse(data)
        case let .ellipse(center, rx, ry, degrees):
            Path(ellipseIn: CGRect(x: -rx, y: -ry, width: rx * 2, height: ry * 2))
                .applying(CGAffineTransform(rotationAngle: degrees * .pi / 180)
                    .concatenating(CGAffineTransform(translationX: center.x, y: center.y)))
        }
    }

    var shading: GraphicsContext.Shading {
        switch fill {
        case .solid(let color): .color(color)
        case let .linear(stops, from, to): .linearGradient(Gradient(stops: stops), startPoint: from, endPoint: to)
        case let .radial(stops, center, radius):
            .radialGradient(Gradient(stops: stops), center: center, startRadius: 0, endRadius: radius)
        }
    }
}

/// Minimal parser for the absolute M/L/C/Z path data the generator emits.
enum SVGPath {
    static func parse(_ data: String) -> Path {
        var path = Path()
        var command: Character = "M"
        var numbers: [CGFloat] = []

        func flush() {
            var i = 0
            func point() -> CGPoint {
                defer { i += 2 }
                return CGPoint(x: numbers[i], y: numbers[i + 1])
            }
            switch command {
            case "M":
                guard numbers.count >= 2 else { break }
                path.move(to: point())
                while i + 1 < numbers.count { path.addLine(to: point()) }
            case "L":
                while i + 1 < numbers.count { path.addLine(to: point()) }
            case "C":
                while i + 5 < numbers.count {
                    let c1 = point(), c2 = point(), end = point()
                    path.addCurve(to: end, control1: c1, control2: c2)
                }
            case "Z":
                path.closeSubpath()
            default:
                break
            }
            numbers.removeAll(keepingCapacity: true)
        }

        var token = ""
        func endToken() {
            if let value = Double(token) { numbers.append(CGFloat(value)) }
            token = ""
        }
        for character in data {
            if character.isLetter {
                endToken()
                flush()
                command = character
            } else if character == "," || character == " " {
                endToken()
            } else if character == "-" && !token.isEmpty {
                endToken()
                token.append(character)
            } else {
                token.append(character)
            }
        }
        endToken()
        flush()
        return path
    }
}

/// Full-color app mark drawn as vectors, crisp at any size.
struct HyenaMark: View {
    var size: CGFloat = 36
    /// Adds the standard macOS icon drop shadow (used for exported icons).
    var iconShadow = false
    /// Fills the whole square edge to edge (GitHub avatars crop their own shape).
    var fullBleed = false

    var body: some View {
        Canvas { context, canvasSize in
            if fullBleed {
                // Map the 824-pt icon body onto the whole canvas.
                let scale = canvasSize.width / LogoArtwork.body.width
                context.scaleBy(x: scale, y: scale)
                context.translateBy(x: -LogoArtwork.body.minX, y: -LogoArtwork.body.minY)
            } else {
                let scale = canvasSize.width / LogoArtwork.canvas
                context.scaleBy(x: scale, y: scale)
            }
            let body = fullBleed
                ? Path(LogoArtwork.body)
                : Path(roundedRect: LogoArtwork.body, cornerRadius: LogoArtwork.cornerRadius, style: .continuous)

            if iconShadow {
                var shadow = context
                shadow.addFilter(.shadow(color: .black.opacity(0.35), radius: 14, x: 0, y: 10))
                shadow.fill(body, with: .color(.black))
            }
            context.fill(body, with: .linearGradient(
                LogoArtwork.background, startPoint: CGPoint(x: 265, y: 100), endPoint: CGPoint(x: 594, y: 924)
            ))
            context.drawLayer { inner in
                inner.clip(to: body)
                for layer in LogoArtwork.layers {
                    if let width = layer.strokeWidth {
                        inner.stroke(layer.path, with: layer.shading,
                                     style: StrokeStyle(lineWidth: width, lineCap: .round))
                    } else {
                        inner.fill(layer.path, with: layer.shading)
                    }
                }
            }
            if fullBleed { return }
            context.stroke(
                Path(roundedRect: LogoArtwork.body.insetBy(dx: 1, dy: 1), cornerRadius: LogoArtwork.cornerRadius - 1,
                     style: .continuous),
                with: .linearGradient(
                    Gradient(colors: [.white.opacity(0.28), .white.opacity(0.04)]),
                    startPoint: CGPoint(x: 512, y: 100), endPoint: CGPoint(x: 512, y: 924)
                ),
                lineWidth: 2
            )
        }
        .frame(width: size, height: size)
        .accessibilityLabel("Hyena")
    }
}

@MainActor
enum HyenaGlyph {
    /// Template image for the menu bar: the hyena head in profile.
    static let menuBarImage: NSImage = image(pointSize: 18)

    static func image(pointSize: CGFloat) -> NSImage {
        // Crop around the head and the top of the mane.
        let crop = CGRect(x: 200, y: 140, width: 700, height: 700)
        let image = NSImage(size: NSSize(width: pointSize, height: pointSize), flipped: true) { rect in
            guard let context = NSGraphicsContext.current?.cgContext else { return false }
            let scale = rect.width / crop.width
            context.scaleBy(x: scale, y: scale)
            context.translateBy(x: -crop.minX, y: -crop.minY)
            context.setFillColor(NSColor.black.cgColor)
            for data in LogoArtwork.glyphFill {
                context.addPath(SVGPath.parse(data).cgPath)
                context.fillPath()
            }
            context.setBlendMode(.clear)
            for data in LogoArtwork.glyphCutouts {
                context.addPath(SVGPath.parse(data).cgPath)
                context.fillPath()
            }
            context.setLineWidth(22)
            context.setLineCap(.round)
            context.addPath(SVGPath.parse(LogoArtwork.glyphGrin).cgPath)
            context.strokePath()
            return true
        }
        image.isTemplate = true
        image.accessibilityDescription = "Hyena"
        return image
    }
}

/// `Hyena --render-icon <iconset-dir>` writes the app icon PNGs.
/// `Hyena --render-avatar <file.png>` writes a 1024 px edge-to-edge avatar.
@MainActor
enum IconExporter {
    static func avatar(output: String) -> Int32 {
        let renderer = ImageRenderer(content: HyenaMark(size: 1024, fullBleed: true))
        renderer.scale = 1
        guard let cgImage = renderer.cgImage,
              let png = NSBitmapImageRep(cgImage: cgImage).representation(using: .png, properties: [:]) else { return 1 }
        do { try png.write(to: URL(fileURLWithPath: output)) } catch { return 1 }
        return 0
    }

    static func run(output: String) -> Int32 {
        let directory = URL(fileURLWithPath: output, isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let sizes: [(String, CGFloat)] = [
            ("16x16", 16), ("16x16@2x", 32), ("32x32", 32), ("32x32@2x", 64),
            ("128x128", 128), ("128x128@2x", 256), ("256x256", 256), ("256x256@2x", 512),
            ("512x512", 512), ("512x512@2x", 1024),
        ]
        for (name, pixels) in sizes {
            let renderer = ImageRenderer(content: HyenaMark(size: pixels, iconShadow: true))
            renderer.scale = 1
            guard let cgImage = renderer.cgImage else { return 1 }
            let rep = NSBitmapImageRep(cgImage: cgImage)
            guard let png = rep.representation(using: .png, properties: [:]) else { return 1 }
            do {
                try png.write(to: directory.appendingPathComponent("icon_\(name).png"))
            } catch {
                FileHandle.standardError.write(Data("\(error)\n".utf8))
                return 1
            }
        }
        return 0
    }
}
